css:
.loader { position: relative; display: inline-flex; align-items: center; justify-content: center; width: var(--loader-size); height: var(--loader-size); }
.loader .halo { position: absolute; inset: 0; border-radius: 9999px; background: var(--loader-color); opacity: .75; animation: twPing calc(var(--loader-speed) * 1.2) cubic-bezier(0, 0, .2, 1) infinite; }
.loader::after { content: ''; position: relative; width: 56%; height: 56%; border-radius: 9999px; background: var(--loader-color); }
@keyframes twPing { 70%, 100% { transform: scale(2.1); opacity: 0; } }
